/* CM1 base address */
pub const OMAP4430_CM1_BASE: u32 = 0x4a004000;

/*
 * OMAP2_L4_IO_ADDRESS is supplied by the surrounding translation unit.
 * This macro preserves the original register-address calculation.
 */
macro_rules! OMAP44XX_CM1_REGADDR {
    ($inst:expr, $reg:expr) => {
        OMAP2_L4_IO_ADDRESS(OMAP4430_CM1_BASE + ($inst) + ($reg))
    };
}

/* CM1 instances */
pub const OMAP4430_CM1_OCP_SOCKET_INST: u32 = 0x0000;
pub const OMAP4430_CM1_CKGEN_INST: u32 = 0x0100;
pub const OMAP4430_CM1_MPU_INST: u32 = 0x0300;
pub const OMAP4430_CM1_TESLA_INST: u32 = 0x0400;
pub const OMAP4430_CM1_ABE_INST: u32 = 0x0500;

/* CM1 clockdomain register offsets (from instance start) */
pub const OMAP4430_CM1_MPU_MPU_CDOFFS: u32 = 0x0000;
pub const OMAP4430_CM1_TESLA_TESLA_CDOFFS: u32 = 0x0000;
pub const OMAP4430_CM1_ABE_ABE_CDOFFS: u32 = 0x0000;

